"""Facility codes are generated by the server: WH-0001-26."""
import datetime
import re
from unittest import mock

from hospitals.models import Hospital

from .base import WakaraTestCase

PATTERN = re.compile(r'^WH-(\d{4,})-(\d{2})$')


class HospitalCodeTests(WakaraTestCase):
    def create(self, name, **extra):
        return self.client_for(self.admin).post('/api/hospitals/', {'name': name, **extra}, format='json')

    def test_code_is_generated_incremented_and_returned(self):
        yy = datetime.date.today().year % 100
        a, b = self.create('Maternité A'), self.create('Maternité B')
        self.assertEqual(a.status_code, 201, a.content)
        self.assertEqual(a.data['code'], f'WH-0001-{yy:02d}')
        self.assertEqual(b.data['code'], f'WH-0002-{yy:02d}')
        listing = self.client_for(self.admin).get('/api/hospitals/').data['results']
        self.assertIn(f'WH-0002-{yy:02d}', [h['code'] for h in listing])

    def test_code_cannot_be_supplied_or_modified(self):
        r = self.create('Clinique C', code='MON-CODE')
        self.assertEqual(r.status_code, 201)
        self.assertRegex(r.data['code'], PATTERN)
        self.assertNotEqual(r.data['code'], 'MON-CODE')
        patched = self.client_for(self.admin).patch(f'/api/hospitals/{r.data["uuid"]}/', {'code': 'HACK', 'name': 'Clinique C2'}, format='json')
        self.assertEqual(patched.status_code, 200)
        self.assertEqual(patched.data['code'], r.data['code'])
        self.assertEqual(patched.data['name'], 'Clinique C2')

    def test_numbering_restarts_each_year_and_year_suffix_changes(self):
        with mock.patch('hospitals.services.timezone.localdate', return_value=datetime.date(2026, 12, 31)):
            self.assertEqual(self.create('Fin 2026').data['code'], 'WH-0001-26')
            self.assertEqual(self.create('Fin 2026 bis').data['code'], 'WH-0002-26')
        with mock.patch('hospitals.services.timezone.localdate', return_value=datetime.date(2027, 1, 2)):
            self.assertEqual(self.create('Début 2027').data['code'], 'WH-0001-27')

    def test_every_creation_path_gets_a_unique_code(self):
        codes = {Hospital.objects.create(name=f'Direct {i}').code for i in range(5)}
        self.assertEqual(len(codes), 5)
        self.assertTrue(all(PATTERN.match(c) for c in codes))

    def test_declaration_exposes_the_facility_code(self):
        d = self.create_declaration(self.agent, hospital=str(self.hospital.uuid))
        r = self.client_for(self.agent).get(f'/api/declarations/{d["uuid"]}/')
        self.assertEqual(r.data['hospital_code'], 'CMC')  # the fixture facility keeps its explicit code
